WITH scored AS (SELECT b.record_id,rank AS relevance,b.id AS block_id FROM content_search JOIN content_blocks b INDEXED BY content_block_identity ON b.id=content_search.rowid WHERE content_search MATCH ? LIMIT -1), documents AS (SELECT record_id,min(relevance) AS relevance,block_id FROM scored GROUP BY record_id) SELECT d.record_id,d.relevance,d.block_id FROM documents d JOIN available_search_records r ON r.id=d.record_id LEFT JOIN workspace w ON w.record_id=r.id WHERE w.trashed IS NULL ORDER BY d.relevance,d.record_id LIMIT 101